namespace ghidra.asm.wild.sem;



using ghidra.app.plugin.assembler.sleigh.sem;
using ghidra.app.plugin.processors.sleigh.symbol;
using ghidra.asm.wild.tree;

public class WildAssemblyFixedNumericStateGenerator : AbstractAssemblyStateGenerator<WildAssemblyParseToken> {

	protected OperandSymbol opSym;
	protected long val;

	public WildAssemblyFixedNumericStateGenerator(
			AbstractAssemblyTreeResolver<object> resolver, WildAssemblyParseToken node,
			OperandSymbol opSym, long val, AssemblyResolvedPatterns fromLeft) : base(resolver, node, fromLeft)
    {
		this.opSym = opSym;
		this.val = val;
	}

	/* @Override */
	public Stream<AssemblyGeneratedPrototype> generate(GeneratorContext gc) {
		if (!node.wild.test(val)) {
			return Stream.of();
		}
		return Stream.of(
			new AssemblyGeneratedPrototype(new WildAssemblyOperandState(resolver, gc.path, gc.shift,
				node.getSym(), val, opSym, node.wildcardName(), val), fromLeft));
	}
}
